mapper.select:
select m.id, m.project_id, m.submit_time, m.contact_name, m.contact_phone, m.result_type, m.archive_dir, m.submit_status, m.guarantor_flag, m.guarantor_id, m.guarantor_name, m.archive_flag, m.archive_time, as status, m.extra_data::text as extra_data, m.del_flag, m.create_by, m.create_time, m.update_by, m.update_time, m.remark, p.project_name, p.project_code, p.engineering_project, p.project_location, (select f.operate_time from proj_material_flow f where f.material_id = m.id and f.flow_type = '领取' and f.del_flag = '0' order by f.operate_time desc limit 1) as receive_time from proj_material m left join proj_project p on p.id = m.project_id where m.del_flag = '0'
and m.project_id = #{projectId}
and m.contact_name like concat('%', #{contactName}, '%')
and m.result_type = #{resultType}
and () = #{status}
and m.archive_flag = #{archiveFlag}
and p.status in
#{s}
AND m.submit_status = #{submitStatus}
AND (m.contact_name like concat('%', #{keyword}, '%') or m.archive_dir like concat('%', #{keyword}, '%') or p.project_code like concat('%', #{keyword}, '%') or p.project_name like concat('%', #{keyword}, '%'))
AND m.submit_time >= #{submitTimeBegin}
AND m.submit_time <= #{submitTimeEnd}
AND m.contact_phone like concat('%', #{contactPhone}, '%')
AND p.project_code like concat('%', #{projectCode}, '%')
AND p.project_location like concat('%', #{projectLocation}, '%')
AND p.contract_id = #{contractId}
AND p.data_source = #{dataSource}
AND p.client_unit_nature = #{clientUnitNature}
AND p.close_time >= to_date(#{closeDateBegin}, 'YYYY-MM-DD')
AND p.close_time < to_date(#{closeDateEnd}, 'YYYY-MM-DD') + interval '1 day'
order by m.id desc

mapper.update:
update proj_material
project_id = #{projectId}, submit_time = #{submitTime}, contact_name = #{contactName}, contact_phone = #{contactPhone}, result_type = #{resultType}, archive_dir = #{archiveDir}, status = #{status}, submit_status = #{submitStatus}, guarantor_flag = #{guarantorFlag}, guarantor_id = null, guarantor_name = null, guarantor_id = #{guarantorId}, guarantor_name = #{guarantorName}, archive_flag = #{archiveFlag}, archive_time = now(), archive_time = null, extra_data = #{extraData}::jsonb, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where id = #{id}

update proj_material set del_flag = '2' where project_id in
#{projectId}
and del_flag = '0'

update proj_material set archive_flag = #{archiveFlag},
archive_time = now(), archive_time = null,
update_time = now(), update_by = #{updateBy} where id = #{id}
